/* C API of the Rust port of `avstring.c`, generated by everything-rust. */
#ifndef AVSTRING_RS_H
#define AVSTRING_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

int av_strstart(const char *str, const char *pfx, const char **ptr);
int av_stristart(const char *str, const char *pfx, const char **ptr);
char *av_stristr(const char *s1, const char *s2);
char *av_strnstr(const char *haystack, const char *needle, size_t hay_length);
size_t av_strlcpy(char *dst, const char *src, size_t size);
size_t av_strlcat(char *dst, const char *src, size_t size);
int av_strcasecmp(const char *a, const char *b);
int av_strncasecmp(const char *a, const char *b, size_t n);
int av_match_name(const char *name, const char *names);
int av_match_list(const char *name, const char *list, char separator);

/* The same functions under `everything_rust_` names, for shadow runs. */
int everything_rust_av_strstart(const char *str, const char *pfx, const char **ptr);
int everything_rust_av_stristart(const char *str, const char *pfx, const char **ptr);
char *everything_rust_av_stristr(const char *s1, const char *s2);
char *everything_rust_av_strnstr(const char *haystack, const char *needle, size_t hay_length);
size_t everything_rust_av_strlcpy(char *dst, const char *src, size_t size);
size_t everything_rust_av_strlcat(char *dst, const char *src, size_t size);
int everything_rust_av_strcasecmp(const char *a, const char *b);
int everything_rust_av_strncasecmp(const char *a, const char *b, size_t n);
int everything_rust_av_match_name(const char *name, const char *names);
int everything_rust_av_match_list(const char *name, const char *list, char separator);

#endif /* AVSTRING_RS_H */
